@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Gowun+Batang:wght@400;700&family=IBM+Plex+Sans+KR:wght@400;500;600;700&display=swap');
:root{--bg:#101114;--panel:#17181b;--panel2:#1d1e22;--line:#34353a;--muted:#88898e;--paper:#e9e6df;--red:#cf493d;--gold:#d4ad72;--mono:'DM Mono',monospace;--sans:'IBM Plex Sans KR',sans-serif;--serif:'Gowun Batang',serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--paper);font-family:var(--sans);min-height:100vh}.grain{position:fixed;inset:0;pointer-events:none;opacity:.035;z-index:10;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E")}.game-shell{max-width:1440px;margin:auto;padding:0 56px}.topbar{height:74px;border-bottom:1px solid #2d2e32;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:34px;height:34px;border:1px solid #9a7a4c;color:var(--gold);display:grid;place-items:center;font-size:23px}.brand b{font:500 10px var(--mono);letter-spacing:1.6px;color:#c1bdb5;display:block}.brand span{font-size:11px;color:#78797e;display:block;margin-top:3px;letter-spacing:1.5px}.chapter{font:11px var(--mono);letter-spacing:1px;color:#9d9da0}.chapter i{font-style:normal;color:var(--red);margin:0 7px}.top-actions{display:flex;align-items:center;gap:10px}.round-pill{font-size:10px;color:#b1b0aa;border:1px solid #393a3e;padding:7px 10px;border-radius:20px}.live-dot,.phase-dot{display:inline-block;width:6px;height:6px;background:#a84238;border-radius:50%;margin-right:7px;box-shadow:0 0 9px #c34a3b}.icon-btn{width:30px;height:30px;border:1px solid #37383b;background:none;color:#b9b7b0;border-radius:50%;cursor:pointer;font-size:13px}.stage{height:382px;margin-top:20px;position:relative;overflow:hidden;border:1px solid #393332;background:linear-gradient(180deg,rgba(13,15,17,.06),rgba(12,13,16,.22) 50%,rgba(12,13,16,.8)),radial-gradient(ellipse at 50% 108%,#595050 0,#36363a 27%,transparent 62%),linear-gradient(113deg,#33302d 0%,#252629 40%,#34302d 100%)}.stage:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent 0 9%,#b5a68d08 9.1% 9.3%,transparent 9.4% 31%,#ddd1bd0b 31.2% 31.4%,transparent 31.5% 68%,#ddd1bd08 68.2% 68.4%,transparent 68.5% 90%,#ddd1bd08 90.2% 90.4%,transparent 90.5%),linear-gradient(0deg,#0005 1px,transparent 1px);background-size:auto,100% 85px;opacity:.9}.stage:after{content:"";position:absolute;width:60%;height:100%;left:20%;top:0;background:radial-gradient(ellipse at 50% 80%,#a24d3022,transparent 55%);pointer-events:none}.stage-top{position:absolute;z-index:2;inset:20px 24px auto;display:flex;justify-content:space-between;align-items:flex-start}.encounter small,.objective small{display:block;color:#a6a29a;font:9px var(--mono);letter-spacing:1.4px;text-transform:uppercase}.encounter strong,.objective strong{display:block;font:16px var(--serif);margin:4px 0}.encounter span,.objective span{font-size:10px;color:#aaa9a4}.danger{color:#df7367;font-weight:500}.objective{text-align:right}.turn-marker{position:absolute;left:50%;top:0;transform:translateX(-50%);background:#121315d9;border:1px solid #58504a;padding:8px 17px;text-align:center;min-width:87px}.turn-marker span{font:8px var(--mono);letter-spacing:2px;color:#a9a39a;display:block}.turn-marker b{font:24px var(--mono);color:var(--gold)}.turn-marker i{font:10px var(--mono);color:#727176;font-style:normal}.combatants{position:absolute;inset:0;z-index:1}.figure{position:absolute;bottom:40px;width:118px;height:214px;display:flex;align-items:center;flex-direction:column;transition:filter .25s,transform .25s;cursor:pointer}.figure.enemy{width:105px;height:198px}.figure:hover{filter:brightness(1.18)}.figure.selected-target{filter:drop-shadow(0 0 9px #db6456);transform:translateY(-5px)}.figure.dead{opacity:.23;filter:grayscale(1);transform:scale(.88)}.figure .name-tag{position:absolute;top:-32px;text-align:center;white-space:nowrap;font-size:10px;color:#ddd9d2;background:#131416d9;padding:4px 9px;border:1px solid #4a4541}.figure.enemy .name-tag{color:#e77b6c}.portrait{position:relative;width:115px;height:160px;overflow:hidden;filter:drop-shadow(0 10px 7px #0008)}.enemy .portrait{width:105px;height:143px}.portrait svg{width:100%;height:100%}.shadow{position:absolute;bottom:0;width:120px;height:16px;background:radial-gradient(ellipse,#08090b99,transparent 70%)}.unit-bar{position:absolute;bottom:-27px;width:115px}.bar-row{display:flex;justify-content:space-between;align-items:center;font:9px var(--mono);margin-bottom:3px;color:#d4d0c8}.bar-track{height:4px;background:#111;border:1px solid #333}.bar-fill{height:100%;background:#c24439;transition:width .5s}.enemy .bar-fill{background:#a44c43}.figure .sp-track{margin-top:3px;height:2px;background:#151515}.figure .sp-fill{height:100%;background:#7890a0}.status-chip{position:absolute;top:7px;right:-11px;font:8px var(--mono);background:#792e2a;padding:4px 5px;color:white;letter-spacing:1px}.target-line{position:absolute;left:50%;bottom:119px;height:1px;width:0;background:#e96654;opacity:0;z-index:3;pointer-events:none}.target-line.active{opacity:.7;animation:draw .35s ease-out forwards}@keyframes draw{to{width:30%}}.stage-bottom{z-index:2;position:absolute;bottom:14px;left:18px;right:18px;display:flex;align-items:flex-end;justify-content:space-between}.weather{display:flex;gap:9px;align-items:center}.weather-icon{width:28px;height:28px;display:grid;place-items:center;border:1px solid #696155;color:var(--gold);font-size:19px}.weather b,.weather small{display:block}.weather b{font:11px var(--serif);color:#d1c9bd}.weather small{font-size:9px;color:#8e8d8a;margin-top:3px}.stage-hint{font:9px var(--mono);color:#aaa8a1}.keycap{border:1px solid #5b5853;padding:3px 5px;color:#d3d0c8}.resource{display:flex;align-items:center;gap:7px;font:9px var(--mono);color:#c6c0b5}.resource>span:first-child{color:#d1b782}.resource-dots{display:flex;gap:3px}.resource-dots i{width:7px;height:7px;border:1px solid #78694f;display:block;transform:rotate(45deg)}.resource-dots i.on{background:#d6ad6c;box-shadow:0 0 7px #c89446}.resource> b{font-size:11px}.resource-label{color:#777}.command{margin-top:21px;background:var(--panel);border:1px solid #34353a;padding:17px 20px 14px}.command-head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:14px}.eyebrow{font:9px var(--mono);letter-spacing:1.7px;color:var(--gold)}.eyebrow span{color:#717176}.command h1{font:21px var(--serif);font-weight:400;margin:5px 0 0;letter-spacing:-.3px}.period{color:var(--red)}.phase-status{font-size:10px;color:#a6a39c;padding-bottom:4px}.phase-dot{background:#b88c57;box-shadow:0 0 7px #c7985f}.squad{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.sinner{min-width:0;background:#1d1e22;border:1px solid #393a3e;padding:10px 11px 9px;position:relative;transition:border-color .2s,opacity .2s}.sinner.is-dead{opacity:.42}.sinner-head{display:flex;align-items:center;gap:9px;margin-bottom:9px}.mini-portrait{width:32px;height:35px;background:#3c3531;overflow:hidden;border:1px solid #635449}.mini-portrait svg{width:100%;height:100%}.identity{flex:1;min-width:0}.identity b{display:block;font:12px var(--serif);white-space:nowrap}.identity small{display:block;color:#88878a;font:8px var(--mono);letter-spacing:.5px;margin-top:3px}.identity .identity-hp{font:8px var(--mono);color:#aaa;margin-top:3px}.skill-options{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.skill{position:relative;text-align:left;background:#25262a;color:#ddd;border:1px solid #404146;min-height:55px;padding:6px 6px 5px;cursor:pointer;transition:all .15s}.skill:hover{background:#303034;border-color:#817052}.skill.active{border-color:var(--gold);background:#3a332a;box-shadow:inset 0 0 0 1px #b58e5b55}.skill:disabled{opacity:.35;cursor:not-allowed}.skill-top{display:flex;justify-content:space-between;align-items:center}.skill-name{font-size:9px;font-weight:600;white-space:nowrap}.skill-index{font:8px var(--mono);color:#888}.skill-meta{display:flex;align-items:center;gap:5px;margin-top:7px;color:#aaa;font:8px var(--mono)}.skill-power{color:#d8b67e;font-size:10px}.coin{width:8px;height:8px;border:1px solid #bd975d;border-radius:50%;display:inline-block;vertical-align:middle;margin-left:2px}.skill-ego{position:absolute;right:5px;bottom:5px;font:7px var(--mono);color:#e4a77b}.skill-type{display:inline-block;width:5px;height:10px;margin-right:3px;vertical-align:-1px}.slash{background:#c26359}.pierce{background:#8aa2ad}.blunt{background:#c6a45e}.command-footer{display:flex;align-items:center;justify-content:space-between;margin-top:12px}.legend{display:flex;align-items:center;gap:12px;color:#96969a;font-size:9px}.legend>span{white-space:nowrap}.legend-chip{display:inline-block;width:5px;height:10px;margin-right:5px;vertical-align:-1px}.tip{border-left:1px solid #3c3d41;padding-left:13px;color:#77787e}.execute{border:1px solid #a3493d;background:#a43d33;color:white;padding:10px 14px;min-width:174px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;font:11px var(--sans);transition:all .2s}.execute b{font:16px var(--mono)}.execute:hover:not(:disabled){background:#c34d3d;box-shadow:0 0 18px #a43d3344}.execute:disabled{border-color:#464247;background:#28272a;color:#777;cursor:not-allowed}.logbar{margin-top:11px;border-top:1px solid #303135;display:flex;align-items:center;min-height:39px;gap:18px;color:#959499}.log-title{font:9px var(--mono);letter-spacing:.8px;white-space:nowrap}.log-pulse{display:inline-block;width:5px;height:5px;background:#ae5446;border-radius:50%;margin-right:7px}.log-feed{flex:1;font-size:10px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.log-feed .log-muted{color:#737379}.log-toggle{display:none;background:none;border:0;color:#888;font:9px var(--mono)}.toast{position:fixed;z-index:20;top:92px;left:50%;transform:translate(-50%,-10px);opacity:0;background:#292323;border:1px solid #7d453a;padding:9px 15px;font-size:11px;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.overlay,.modal{position:fixed;inset:0;z-index:30;background:#090a0bcc;backdrop-filter:blur(7px);display:grid;place-items:center;padding:20px}.hidden{display:none!important}.result-card,.modal-card{max-width:480px;width:100%;padding:38px;background:#191a1d;border:1px solid #6b5344;text-align:center;box-shadow:0 20px 100px #0009}.result-symbol{color:var(--gold);font-size:34px}.result-card small,.modal-card>small{font:9px var(--mono);color:#ba9d70;letter-spacing:2px}.result-card h2,.modal-card h2{font:25px var(--serif);margin:10px 0}.result-card p{color:#aaa;font-size:12px;line-height:1.8}.result-card button{margin-top:14px;border:1px solid #a64b3c;background:#9d3e34;color:white;padding:11px 20px;font:11px var(--sans);cursor:pointer}.result-card button span{margin-left:20px}.modal-card{text-align:left;position:relative}.modal-card h2{margin-bottom:18px}.modal-card p{font-size:12px;line-height:1.8;color:#aaa}.modal-card p b{color:#e3c28b}.modal-close{position:absolute;right:15px;top:12px;background:none;border:0;color:#aaa;font-size:23px;cursor:pointer}.manual-note{border-top:1px solid #38383c;padding-top:14px;color:#887968;font:10px var(--serif);margin-top:20px}
