.log-toggle{display:block}.logbar.expanded{align-items:flex-start;flex-wrap:wrap;padding:9px 0}.logbar.expanded .log-feed{white-space:normal;flex-basis:100%;order:3;line-height:1.8}.result-card,.modal-card{padding:28px 20px}}

