function renderStage(){combatants.innerHTML=people.map((p,i)=>figureMarkup(p,false,i)).join('')+enemies.map((e,i)=>figureMarkup(e,true,i)).join('');$('#resourceCount').textContent=resonance;$('#resourceDots').innerHTML=Array.from({length:6},(_,i)=>`<i class="${i<resonance?'on':''}"></i>`).join('');$('#turnNum').textContent=String(turn).padStart(2,'0');combatants.querySelectorAll('.enemy').forEach(el=>el.addEventListener('click',()=>setTarget(el.dataset.id)));}
function miniArt(i){return allyArt[i]}
function renderSquad(){squad.innerHTML=people.map((p,i)=>`<article class="sinner ${p.hp<=0?'is-dead':''}"><div class="sinner-head"><div class="mini-portrait">${miniArt(i)}</div><div class="identity"><b>${p.name}</b><small>${p.role}</small><div class="identity-hp">HP ${Math.max(0,p.hp)} / ${p.max}　·　속도 ${p.speed}</div></div></div><div class="skill-options">${p.skills.map((s,j)=>{const picked=selections[p.id],locked=p.hp<=0||phase!=='command'||(s.ego&&resonance<s.cost);return `<button class="skill ${picked?.idx===j?'active':''}" data-person="${p.id}" data-skill="${j}" ${locked?'disabled':''}><div class="skill-top"><span class="skill-name"><i class="skill-type ${s.type}"></i>${s.name}</span><span class="skill-index">${j+1}</span></div><div class="skill-meta"><span class="skill-power">${s.power}+</span><span>${s.n}<i class="coin"></i></span><span>속도 ${p.speed}</span></div>${s.ego?`<span class="skill-ego">E.G.O · ${s.cost}공명</span>`:''}</button>`}).join('')}</div></article>`).join('');squad.querySelectorAll('.skill').forEach(b=>b.addEventListener('click',()=>selectSkill(b.dataset.person,+b.dataset.skill)));const count=Object.keys(selections).length;$('#executeBtn').disabled=phase!=='command'||count!==people.filter(p=>p.hp>0).length;$('#phaseText').textContent=phase==='command'?`${count} / ${people.filter(p=>p.hp>0).length} 행동 선택`:'충돌 진행 중';}
function selectSkill(id,idx){if(phase!=='command')return;const p=people.find(x=>x.id===id),s=p.skills[idx];if(s.ego&&resonance<s.cost)return;if(selections[id]?.idx===idx){delete selections[id]}else selections[id]={idx,target:selections[id]?.target||'e1'};renderSquad();}
function setTarget(id){if(phase!=='command')return;const chosen=Object.keys(selections);if(!chosen.length){toast('먼저 행동을 선택하세요.');return}const idToSet=chosen[chosen.length-1];selections[idToSet].target=id;renderStage();renderSquad();say(`${people.find(p=>p.id===idToSet).name} → ${enemies.find(e=>e.id===id)?.name||'대상'}`)}
function say(text){logItems.unshift(text);logItems=logItems.slice(0,8);$('#logFeed').innerHTML=logItems.map((x,i)=>`<span style="color:${i===0?'#d8cbb5':'#8c8a87'}">${x}</span>`).join('　<span style="color:#555">/</span>　')}
let toastTimer;function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1800)}
function flip(chance){return Math.random()*100<chance}function sanityChance(u){return Math.max(5,Math.min(95,50+u.sp*.5))}function roll(skill,u){let heads=0;for(let i=0;i<skill.n;i++){const h=flip(sanityChance(u));if(h)heads++}return skill.power+heads*skill.coin}
function enemySkill(e){return {name:'잔향의 타격',power:e.atk,coin:3,n:e.n}}
function damage(target,amount){let dmg=Math.max(1,Math.round(amount*(target.staggered?1.5:1)));target.hp=Math.max(0,target.hp-dmg);if(!target.isEnemy)target.sp=Math.max(-45,target.sp-4);if(target.hp<=target.max*.35&&!target.staggered&&target.hp>0){target.staggered=true;say(`${target.name} — 흐트러짐!`)}return dmg}
function triggerFlash(id){const el=combatants.querySelector(`[data-id="${id}"]`);if(el){el.animate([{filter:'brightness(1)'},{filter:'brightness(3) sepia(1)',transform:'translateY(-13px)'},{filter:'brightness(1)',transform:'translateY(0)'}],{duration:420})}}
function clash(player,skill,enemy){const es=enemySkill(enemy);const pc=roll(skill,player),ec=roll(es,enemy);const won=pc>=ec;const text=`${player.name} [${pc}] ${won?'승리':'패배'} [${ec}] ${enemy.name}`;say(text);triggerFlash(won?enemy.id:player.id);if(won){const d=damage(enemy,pc+Math.max(0,skill.n-1)*2);say(`${enemy.name}에게 ${d} 피해`);player.sp=Math.min(45,player.sp+3);resonance=Math.min(6,resonance+1);if(skill.ego)resonance=Math.max(0,resonance-skill.cost)}else{const d=damage(player,ec);say(`${player.name}이(가) ${d} 피해`);player.sp=Math.max(-45,player.sp-5);enemy.sp=Math.min(45,enemy.sp+3)}}
function unopposed(player,skill,enemy){const power=roll(skill,player);const d=damage(enemy,power+skill.n*2);say(`${player.name}의 ${skill.name} — ${enemy.name}에게 ${d} 피해`);triggerFlash(enemy.id);player.sp=Math.min(45,player.sp+4);resonance=Math.min(6,resonance+1);if(skill.ego)resonance=Math.max(0,resonance-skill.cost)}
function targetEnemyAction(e){if(e.hp<=0)return;const living=people.filter(p=>p.hp>0);if(!living.length)return;const target=living[Math.floor(Math.random()*living.length)];if(target.staggered){say(`${target.name}은(는) 흐트러져 행동할 수 없다.`);return}const attack=enemySkill(e),power=roll(attack,e);const d=damage(target,power);target.sp=Math.max(-45,target.sp-2);say(`${e.name}의 공격 → ${target.name} ${d} 피해`);triggerFlash(target.id)}
async function execute(){if(phase!=='command'||Object.keys(selections).length!==people.filter(p=>p.hp>0).length)return;phase='resolving';renderSquad();$('#executeBtn').innerHTML='<span>충돌을 계산하는 중</span><b>…</b>';$('#executeBtn').disabled=true;say(`— TURN ${String(turn).padStart(2,'0')} —`);await wait(450);
// Faster actions resolve first; a direct enemy attack is intercepted as a clash.
const actions=people.filter(p=>p.hp>0&&!p.staggered).map(p=>({p,sel:selections[p.id],speed:p.speed+Math.floor(Math.random()*3)})).sort((a,b)=>b.speed-a.speed);
const usedEnemies=new Set();for(const a of actions){if(a.p.hp<=0)continue;const enemy=enemies.find(e=>e.id===a.sel.target&&e.hp>0);if(!enemy){say(`${a.p.name}의 목표가 사라졌다.`);continue}const skill=a.p.skills[a.sel.idx];const enemyTargetsPlayer=enemy.hp>0&&a.speed>=enemy.speed+Math.floor(Math.random()*3)-2;if(enemyTargetsPlayer&&!usedEnemies.has(enemy.id)){clash(a.p,skill,enemy);usedEnemies.add(enemy.id)}else unopposed(a.p,skill,enemy);await wait(520);renderStage();}
for(const e of enemies.filter(e=>e.hp>0&&!usedEnemies.has(e.id))){await wait(300);targetEnemyAction(e);renderStage()}
await wait(500);people.forEach(p=>{p.speed=3+Math.floor(Math.random()*4);if(p.staggered)p.staggered=false});enemies.forEach(e=>{e.speed=2+Math.floor(Math.random()*5);if(e.staggered)e.staggered=false});selections={};turn++;phase='command';renderStage();renderSquad();$('#executeBtn').innerHTML='<span>선택한 행동 실행</span><b>→</b>';if(enemies.every(e=>e.hp<=0))finish(true);else if(people.every(p=>p.hp<=0))finish(false);else say(`새 턴 — 각자의 속도 주사위가 굴러갔다.`)}
function wait(ms){return new Promise(r=>setTimeout(r,ms))}function finish(win){phase='finished';$('#resultSymbol').textContent=win?'✦':'◌';$('#resultKicker').textContent=win?'작전 완료 / CASE CLOSED':'기록 중단 / CASE FAILED';$('#resultTitle').textContent=win?'회랑을 침묵시켰다':'잔향에 삼켜졌다';$('#resultText').textContent=win?`${turn-1}턴 만에 기억의 잔향을 제거했다. 살아남은 이들이 다시 걸음을 옮긴다.`:'기억은 아직 끝나지 않았다. 숨을 고르고, 다른 지시를 내려라.';$('#overlay').classList.remove('hidden')}
$('#executeBtn').addEventListener('click',execute);$('#restartBtn').addEventListener('click',()=>location.reload());$('#helpBtn').addEventListener('click',()=>$('#helpModal').classList.remove('hidden'));$('#closeHelp').addEventListener('click',()=>$('#helpModal').classList.add('hidden'));$('#helpModal').addEventListener('click',e=>{if(e.target.id==='helpModal')e.currentTarget.classList.add('hidden')});$('#logToggle').addEventListener('click',()=>{$('.logbar').classList.toggle('expanded');$('#logToggle').innerHTML=$('.logbar').classList.contains('expanded')?'접기 <span>⌄</span>':'기록 보기 <span>⌃</span>'});$('#soundBtn').addEventListener('click',e=>{e.currentTarget.classList.toggle('muted');toast(e.currentTarget.classList.contains('muted')?'효과음이 꺼졌습니다.':'도시의 소리가 켜졌습니다.')});document.addEventListener('keydown',e=>{if(e.key>='1'&&e.key<='3'&&phase==='command'){const p=people.filter(x=>x.hp>0)[0];if(p)selectSkill(p.id,+e.key-1)}if(e.key==='Tab'&&phase==='command'){e.preventDefault();const live=enemies.filter(x=>x.hp>0),selected=Object.values(selections).at(-1)?.target,idx=live.findIndex(x=>x.id===selected);if(live.length)setTarget(live[(idx+1)%live.length].id)}if(e.key==='Escape')$('#helpModal').classList.add('hidden')});
// Sensible initial choices so the first decision is immediately legible.
selections.ira={idx:0,target:'e1'};renderStage();renderSquad();say('적의 속도 주사위가 굴러갔다. 행동을 선택하고 목표를 지정하라.');

